TTT_PUCT = """
import math
def tictactoe_puct(board, player, sims, c):
    lines = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]
    def result(b):
        for x, y, z in lines:
            if b[x] != '.' and b[x] == b[y] and b[y] == b[z]:
                return b[x]
        if '.' not in b:
            return 'D'
        return '.'
    def flip(p):
        if p == 'X':
            return 'O'
        return 'X'
    tree = {}
    def new_node(b):
        moves = []
        for i in range(9):
            if b[i] == '.':
                moves.append(i)
        k = len(moves)
        return [moves, [1.0 / k] * k, [0] * k, [0.0] * k]
    def simulate(b, p):
        r = result(b)
        if r != '.':
            if r == 'D':
                return 0.0
            if r == p:
                return 1.0
            return -1.0
        key = (b, p)
        if key not in tree:
            tree[key] = new_node(b)
            return 0.0
        node = tree[key]
        moves = node[0]
        P = node[1]
        N = node[2]
        W = node[3]
        total = 0
        for n in N:
            total += n
        root = math.sqrt(total)
        best = -1
        bestscore = None
        for j in range(len(moves)):
            q = 0.0
            if N[j] > 0:
                q = W[j] / N[j]
            s = q + c * P[j] * root / (1 + N[j])
            if bestscore is None or s > bestscore:
                bestscore = s
                best = j
        m = moves[best]
        v = -simulate(b[:m] + p + b[m + 1:], flip(p))
        N[best] += 1
        W[best] += v
        return v
    counts = [0] * 9
    if result(board) != '.':
        return counts
    tree[(board, player)] = new_node(board)
    for i in range(sims):
        simulate(board, player)
    node = tree[(board, player)]
    for j in range(len(node[0])):
        counts[node[0][j]] = node[2][j]
    return counts
"""

